starter.css:
nav { display: flex; gap: 12px; margin-block-end: 12px; }
.active { font-weight: 700; }
.pass { border: 1px solid #c9c4dc; border-radius: 12px; padding: 12px 16px; display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.pass h2 { margin: 0; flex-basis: 100%; font-size: 1.2rem; }
button { font: inherit; padding: 6px 12px; border-radius: 8px; border: 1px solid #5b3cc4; background: #fff; color: #5b3cc4; }
.fav.on, .fav[aria-pressed="true"] { background: #5b3cc4; color: #fff; }
.sticky-bar { margin-block-start: 16px; padding: 8px; background: #f1eefb; }

starter.js:
let count = 0;
const status = document.querySelector('#basket-status');
const fav = document.querySelector('#fav');

function addToBasket() {
  count += 1;
  status.textContent = `Ticket added. ${count} tickets in your basket.`;
}
document.querySelector('#add').addEventListener('click', addToBasket);
document.querySelector('#add-sticky').addEventListener('click', addToBasket);

fav.addEventListener('click', () => {
  fav.classList.toggle('on');
});

