solution.js:
let count = 0;
const status = document.querySelector('#basket-status');
const fav = document.querySelector('#fav');

function addToBasket() {
  count += 1;
  status.textContent = `Ticket added. ${count} tickets in your basket.`;
}
document.querySelector('#add').addEventListener('click', addToBasket);
document.querySelector('#add-sticky').addEventListener('click', addToBasket);

fav.addEventListener('click', () => {
  const saved = fav.getAttribute('aria-pressed') === 'true';
  fav.setAttribute('aria-pressed', String(!saved));
  fav.classList.toggle('on', !saved);
});
